-- ════════════════════════════════════════════════════════
-- 258 — Huitième recensement : les restes des corrections 255 à 257
--       (Ashton et Ashton Cabinet, Boutique Blends, Luciano Cigars,
--       Bock y Ca., la source de Holt's, six descriptions de fiches pays)
-- ────────────────────────────────────────────────────────
-- D'OÙ ÇA VIENT. Un balayage de TOUTES les colonnes texte de la base
-- (history, celebrities, pairings, limited_eds, scores, factory, source,
-- mentions, fiches pays, établissements) a cherché les phrases que les
-- faits des 255 à 257 contredisent encore. Les migrations déjà poussées ne
-- se retouchent pas : la 258 corrige ce qu'elles ont laissé.
--
-- ── CE QUI CHANGE ───────────────────────────────────────
--   Ashton (celebrities)  L'entrée « William Ashton Taylor, détaillant
--                 devenu fabricant » disparaît, ce nom n'étant attesté que
--                 pour les pipes Ashton (la 256 l'avait ôté de l'histoire,
--                 non de cette colonne) : l'entrée dit Robert Levin, Holt's,
--                 1985, les premiers cigares chez Tabadom puis chez Fuente
--                 (1988 selon lui, « peu après le lancement » selon la
--                 maison), dans les six langues.
--   Ashton Cabinet L'histoire commençait par « William Ashton Taylor fonda
--                 Ashton Cigars… » : réécrite sur les mêmes faits ; la
--                 phrase sur le « pari » et sur ce que Taylor tenait pour le
--                 manque de la production dominicaine, sans page, devient une
--                 phrase sur le vieillissement en caisses de cèdre. Son pays
--                 reste l'Équateur : c'est une FICHE DE CAPE voulue (comme
--                 Arturo Fuente Hemingway au Cameroun, Fuente Maduro au
--                 Brésil, CAO Black au Mexique, Oliva Serie G ; sa source le
--                 dit : cape équatorienne sur un cigare roulé chez Fuente, à
--                 Santiago), et non une maison classée par son roulage.
--   Boutique Blends La Bohème, la Quattro Nicaragua et la Pelo de Oro sont
--                 roulées chez A.J. Fernandez (la 256 l'a établi pour Aging
--                 Room) : `factory` et histoire ne disaient que la Palma.
--   Luciano Cigars Ozgener Family Cigars « y fait ses cigares » : elle y a
--                 fait ses premiers en 2022 et les a confiés à La Alianza en
--                 novembre 2022 (Cigar Coop) ; histoire et source.
--   Bock y Ca.    La Libertad n'est plus roulée à l'ABAM mais à Estelí
--                 (Cigar Journal, août 2021 ; Cigar Coop, janvier 2022).
--   Holt's        Le champ `source` citait encore les pages produit et les
--                 avis du personnel de Herfdog, Jalopy, Bottom Shelf et Par,
--                 sorties de la gamme par la 257 (huit citations retirées ;
--                 les motifs restent dans docs/recensement-8-exclus.md), avec
--                 des tournures qui parlaient de notre lecture (« la page ne
--                 dit pas à la main », « rien sur le mode de fabrication »,
--                 « pas d'avis du personnel ») ; « les vingt-quatre noms de la
--                 gamme » devient « les vingt noms ». Chacune des vingt lignes
--                 restantes garde sa page.
--   Fiches pays   Descriptions de marques : Boutique Blends, Tabacalera
--                 Palma (1925 et 1936) et Aging Room (République
--                 dominicaine) ; Miami Cigar & Co., Ozgener, Helvada
--                 (Ammerswil, non Kallern), Tabacosta (ligne Costa seule) et
--                 Luciano Cigars (Nicaragua) ; General Cigar (États-Unis :
--                 Punch et Cohiba vendues par Forged depuis janvier 2026).
--
-- ── EXAMINÉ ET LAISSÉ ───────────────────────────────────
-- Skull 77 (Marc Niehaus « propriétaire de Vegas de Santiago Cigars »,
-- attribué à rauchr.de), Casagranda, Malekö, Gellis Family Cigars (Cloud
-- Hopper en 2016 puis 2017, déjà écrit), E.P. Carrillo (dit déjà Casa
-- Carrillo depuis 2024), Cohiba USA et Partagás USA (fabrique inchangée,
-- seule l'équipe de vente change), Swag (« même atelier » : aucune page de
-- 2024 à 2026 ne la montre, l'éditeur tranche), Villiger (limited_eds « Cuellar
-- Año del Tigre » ; pairings sur Premium No.6 et Export, entrées de machine
-- sorties de la gamme par la règle 187), Atabey et Byron (mots de prix), Asylum
-- et Legado (CLE à Danlí, cohérent).
--
-- Rejouable : chaque remplacement est gardé par la présence du texte
-- ancien (comparé octet par octet), les celebrities sont réécrites en
-- littéral dans chaque langue, les sceaux repassent à `machine`.
-- ════════════════════════════════════════════════════════

-- ── Ashton ──
UPDATE `brands` SET
  `celebrities` = '[{"name":"Robert Levin","anecdote":"Levin est un détaillant devenu créateur de marque : sa famille tient Holt''s, à Philadelphie, depuis 1957, il en dirige les affaires depuis 1974 et crée Ashton en 1985, dit holts.com. Ses premiers cigares furent faits chez Tabadom, puis chez Fuente à partir de 1988 selon lui, ou peu après le lancement selon la maison ; les Ashton sont aujourd''hui roulés à la Tabacalera A. Fuente, en République dominicaine, hors la gamme San Cristobal. C''est une marque entièrement construite sur une relation avec un tiers, et elle ne s''en cache pas."}]',
  `celebrities_en` = '[{"name":"Robert Levin","anecdote":"Levin is a retailer who became a brand creator: his family has kept Holt''s, in Philadelphia, since 1957, he has run its affairs since 1974 and he created Ashton in 1985, says holts.com. His first cigars were made at Tabadom, then at Fuente, from 1988 according to him or shortly after the launch according to the house; Ashton cigars are today rolled at Tabacalera A. Fuente, in the Dominican Republic, except for the San Cristobal range. It is a brand built entirely on a relationship with someone else, and it makes no secret of it."}]',
  `celebrities_es` = '[{"name":"Robert Levin","anecdote":"Levin es un detallista convertido en creador de marca: su familia lleva Holt''s, en Filadelfia, desde 1957, él dirige sus negocios desde 1974 y crea Ashton en 1985, dice holts.com. Sus primeros puros se hicieron en Tabadom, y luego en Fuente, a partir de 1988 según él o poco después del lanzamiento según la casa; los Ashton se lían hoy en la Tabacalera A. Fuente, en la República Dominicana, con excepción de la gama San Cristobal. Es una marca construida por entero sobre una relación con un tercero, y no lo oculta."}]',
  `celebrities_de` = '[{"name":"Robert Levin","anecdote":"Levin ist ein Händler, der zum Markenschöpfer geworden ist: Seine Familie führt Holt''s in Philadelphia seit 1957, er leitet dessen Geschäfte seit 1974 und schafft 1985 Ashton, sagt holts.com. Seine ersten Zigarren wurden bei Tabadom gefertigt, dann bei Fuente, ab 1988 nach seinen Angaben oder kurz nach dem Start nach Angaben des Hauses; die Ashton werden heute in der Tabacalera A. Fuente in der Dominikanischen Republik gerollt, mit Ausnahme der Linie San Cristobal. Eine Marke, die vollständig auf der Beziehung zu einem anderen ruht — und daraus kein Geheimnis macht."}]',
  `celebrities_zh` = '[{"name":"Robert Levin","anecdote":"莱文是零售商出身、后来成为品牌创建者的人：他的家族自1957年起在费城经营 Holt''s，他本人自1974年起掌管其业务，并于1985年创办 Ashton，据 holts.com 称。他最初的雪茄先在 Tabadom 制作，后来在富恩特制作——据他所说是从1988年起，据该公司所说则是品牌推出后不久；Ashton 雪茄如今在多米尼加共和国的 Tabacalera A. Fuente 卷制，San Cristobal 系列除外。这是一个完全建立在他人关系之上的品牌，而它从不讳言这一点。"}]',
  `celebrities_ar` = '[{"name":"Robert Levin","anecdote":"ليفين تاجر تجزئة صار منشئ علامة: تتولّى عائلته Holt''s في فيلادلفيا منذ 1957، ويدير شؤونه منذ 1974، وأنشأ Ashton عام 1985، كما يقول holts.com. صُنعت أولى سيجاراته لدى Tabadom، ثم لدى فوينتي، ابتداءً من 1988 بحسب قوله أو بعد الإطلاق بوقت قصير بحسب الدار؛ وتُلفّ سيجارات Ashton اليوم في Tabacalera A. Fuente بالجمهورية الدومينيكية، عدا خط San Cristobal. علامة قائمة بالكامل على علاقة بطرف آخر، وهي لا تخفي ذلك."}]',
  `updated_at` = NOW()
 WHERE `name` = 'Ashton';

-- ── Ashton Cabinet ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('William Ashton Taylor fonda Ashton Cigars à Philadelphie en 1985, sur une idée qui paraît simple aujourd''hui mais qui ne l''était pas alors : avec le bon approvisionnement en tabac et le bon partenaire de fabrication, la République dominicaine pouvait produire des cigares du plus haut niveau. Le partenaire qu''il choisit fut Arturo Fuente — la maison familiale qui venait de rebâtir sa réputation dans l''île après l''incendie de son usine, en 1980.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'William Ashton Taylor fonda Ashton Cigars à Philadelphie en 1985, sur une idée qui paraît simple aujourd''hui mais qui ne l''était pas alors : avec le bon approvisionnement en tabac et le bon partenaire de fabrication, la République dominicaine pouvait produire des cigares du plus haut niveau. Le partenaire qu''il choisit fut Arturo Fuente — la maison familiale qui venait de rebâtir sa réputation dans l''île après l''incendie de son usine, en 1980.', 'Robert Levin, de la famille qui tient Holt''s à Philadelphie, lance Ashton en 1985, dit holts.com. Ses premiers cigares ne sont pas roulés chez Fuente : il dit dans un entretien de 1996 qu''ils furent d''abord faits par Henke Kelner chez Tabadom, puis qu''il a confié la marque aux Fuente en 1988 ; la maison écrit, elle, qu''il s''est associé aux Fuente peu après le lancement. Les Fuente — la maison familiale qui venait de rebâtir sa réputation dans l''île après l''incendie de son usine, en 1980 — roulent aujourd''hui les Ashton à la Tabacalera A. Fuente, en République dominicaine.'), `history`),
  `history_en` = IF(LOCATE(CAST('William Ashton Taylor founded Ashton Cigars in Philadelphia in 1985 with a premise that seems simple in retrospect but was genuinely unusual at the time: that the Dominican Republic, given the right tobacco sourcing and the right manufacturing partner, could produce cigars of absolute world-class quality. The partner he chose was Arturo Fuente — the family house that had rebuilt its reputation in the Dominican Republic after a catastrophic factory fire in 1980 and was by 1985 acknowledged as the finest manufacturer on the island.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'William Ashton Taylor founded Ashton Cigars in Philadelphia in 1985 with a premise that seems simple in retrospect but was genuinely unusual at the time: that the Dominican Republic, given the right tobacco sourcing and the right manufacturing partner, could produce cigars of absolute world-class quality. The partner he chose was Arturo Fuente — the family house that had rebuilt its reputation in the Dominican Republic after a catastrophic factory fire in 1980 and was by 1985 acknowledged as the finest manufacturer on the island.', 'Robert Levin, of the family that keeps Holt''s in Philadelphia, launched Ashton in 1985, says holts.com. His first cigars were not rolled at Fuente: he says in a 1996 interview that they were first made by Henke Kelner at Tabadom, and that he then entrusted the brand to the Fuentes in 1988; the house, for its part, writes that he teamed up with the Fuentes shortly after the launch. The Fuentes — the family house that had just rebuilt its reputation on the island after the fire at its factory in 1980 — today roll Ashton cigars at Tabacalera A. Fuente, in the Dominican Republic.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('William Ashton Taylor fundó Ashton Cigars en Filadelfia en 1985, sobre una idea que hoy parece simple pero que entonces no lo era: con el buen abastecimiento de tabaco y el buen socio de fabricación, República Dominicana podía producir puros del más alto nivel. El socio que eligió fue Arturo Fuente —la casa familiar que acababa de rehacer su reputación en la isla tras el incendio de su fábrica, en 1980.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'William Ashton Taylor fundó Ashton Cigars en Filadelfia en 1985, sobre una idea que hoy parece simple pero que entonces no lo era: con el buen abastecimiento de tabaco y el buen socio de fabricación, República Dominicana podía producir puros del más alto nivel. El socio que eligió fue Arturo Fuente —la casa familiar que acababa de rehacer su reputación en la isla tras el incendio de su fábrica, en 1980.', 'Robert Levin, de la familia que lleva Holt''s en Filadelfia, lanza Ashton en 1985, dice holts.com. Sus primeros puros no se liaron en Fuente: dice en una entrevista de 1996 que fueron hechos primero por Henke Kelner en Tabadom, y que luego confió la marca a los Fuente en 1988; la casa escribe, por su parte, que se asoció con los Fuente poco después del lanzamiento. Los Fuente —la casa familiar que acababa de rehacer su reputación en la isla tras el incendio de su fábrica, en 1980— lían hoy los Ashton en la Tabacalera A. Fuente, en la República Dominicana.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('William Ashton Taylor gründete Ashton Cigars 1985 in Philadelphia, auf einem Gedanken, der heute einfach wirkt, es damals aber nicht war: Mit der richtigen Tabakbeschaffung und dem richtigen Fertigungspartner konnte die Dominikanische Republik Zigarren auf höchstem Niveau hervorbringen. Der Partner, den er wählte, war Arturo Fuente — das Familienhaus, das seinen Ruf auf der Insel gerade nach dem Brand seiner Fabrik im Jahr 1980 wieder aufgebaut hatte.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'William Ashton Taylor gründete Ashton Cigars 1985 in Philadelphia, auf einem Gedanken, der heute einfach wirkt, es damals aber nicht war: Mit der richtigen Tabakbeschaffung und dem richtigen Fertigungspartner konnte die Dominikanische Republik Zigarren auf höchstem Niveau hervorbringen. Der Partner, den er wählte, war Arturo Fuente — das Familienhaus, das seinen Ruf auf der Insel gerade nach dem Brand seiner Fabrik im Jahr 1980 wieder aufgebaut hatte.', 'Robert Levin, aus der Familie, die Holt''s in Philadelphia führt, brachte Ashton 1985 auf den Markt, sagt holts.com. Seine ersten Zigarren wurden nicht bei Fuente gerollt: Er sagt in einem Interview von 1996, sie seien zunächst von Henke Kelner bei Tabadom hergestellt worden, dann habe er die Marke 1988 den Fuentes anvertraut; das Haus schreibt dagegen, er habe sich kurz nach dem Start mit den Fuentes zusammengetan. Die Fuentes — das Familienhaus, das seinen Ruf auf der Insel nach dem Brand seiner Fabrik im Jahr 1980 gerade erst wieder aufgebaut hatte — rollen die Ashton heute in der Tabacalera A. Fuente in der Dominikanischen Republik.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('1985年，威廉·阿什顿·泰勒在费城创办了阿什顿雪茄，凭的是一个今天看来简单、当时却并不简单的想法：只要有对的烟叶来源与对的制作伙伴，多米尼加共和国就能做出最高水准的雪茄。他选的伙伴是阿图罗·富恩特——那个刚在1980年工厂大火之后，于岛上重建声誉的家族字号。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '1985年，威廉·阿什顿·泰勒在费城创办了阿什顿雪茄，凭的是一个今天看来简单、当时却并不简单的想法：只要有对的烟叶来源与对的制作伙伴，多米尼加共和国就能做出最高水准的雪茄。他选的伙伴是阿图罗·富恩特——那个刚在1980年工厂大火之后，于岛上重建声誉的家族字号。', '罗伯特·莱文（出自在费城经营 Holt''s 的那个家族）于1985年推出 Ashton，据 holts.com 称。他最初的雪茄并不是在富恩特卷制的：他在1996年的一次访谈中说，它们起初由 Henke Kelner 在 Tabadom 制作，后来他在1988年把品牌交给了富恩特家族；该公司则写道，他在品牌推出后不久便与富恩特家族合作。富恩特家族——这家刚在1980年工厂大火之后，于岛上重建声誉的家族字号——如今在多米尼加共和国的 Tabacalera A. Fuente 卷制 Ashton 雪茄。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أسّس ويليام آشتون تايلور شركة «آشتون سيغارز» في فيلادلفيا عام 1985، انطلاقًا من فكرة تبدو اليوم بسيطة ولم تكن كذلك حينها: مع التزوّد الصحيح بالتبغ والشريك الصحيح في الصناعة، تستطيع الجمهورية الدومينيكية أن تنتج سيجارًا من أعلى مستوى. والشريك الذي اختاره كان أرتورو فوينتي — الدار العائلية التي كانت قد أعادت لتوّها بناء سمعتها في الجزيرة بعد حريق مصنعها عام 1980.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أسّس ويليام آشتون تايلور شركة «آشتون سيغارز» في فيلادلفيا عام 1985، انطلاقًا من فكرة تبدو اليوم بسيطة ولم تكن كذلك حينها: مع التزوّد الصحيح بالتبغ والشريك الصحيح في الصناعة، تستطيع الجمهورية الدومينيكية أن تنتج سيجارًا من أعلى مستوى. والشريك الذي اختاره كان أرتورو فوينتي — الدار العائلية التي كانت قد أعادت لتوّها بناء سمعتها في الجزيرة بعد حريق مصنعها عام 1980.', 'أطلق روبرت ليفين، من العائلة التي تتولّى Holt''s في فيلادلفيا، علامة Ashton عام 1985، كما يقول holts.com. ولم تُلفّ أولى سيجاراته لدى فوينتي: يقول في حوار يعود إلى عام 1996 إنها صُنعت في البداية على يد Henke Kelner لدى Tabadom، ثم إنه أوكل العلامة إلى آل فوينتي عام 1988؛ أمّا الدار فتكتب أنه تشارك مع آل فوينتي بعد الإطلاق بوقت قصير. وآل فوينتي — الدار العائلية التي كانت قد أعادت لتوّها بناء سمعتها في الجزيرة بعد حريق مصنعها عام 1980 — يلفّون اليوم سيجار Ashton في Tabacalera A. Fuente بالجمهورية الدومينيكية.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Ashton Cabinet';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La Cabinet Selection est celle qui valide le plus complètement ce pari. Ce n''est pas seulement un cigare haut de gamme : c''est un cigare qui subit un vieillissement supplémentaire, conçu pour répondre à ce que Taylor tenait pour le principal manque d''une production dominicaine par ailleurs excellente — le temps.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La Cabinet Selection est celle qui valide le plus complètement ce pari. Ce n''est pas seulement un cigare haut de gamme : c''est un cigare qui subit un vieillissement supplémentaire, conçu pour répondre à ce que Taylor tenait pour le principal manque d''une production dominicaine par ailleurs excellente — le temps.', 'La Cabinet Selection est la gamme que la maison vieillit après roulage. Ce n''est pas seulement un cigare haut de gamme : c''est un cigare qui subit un vieillissement supplémentaire — le temps que lui donnent les caisses de cèdre.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Cabinet Selection is the expression that validates Taylor''s founding premise most completely. It is not merely a premium cigar — it is a cigar that undergoes an additional aging process specifically designed to address what Taylor considered the main deficiency of otherwise excellent Dominican production: the need for time.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Cabinet Selection is the expression that validates Taylor''s founding premise most completely. It is not merely a premium cigar — it is a cigar that undergoes an additional aging process specifically designed to address what Taylor considered the main deficiency of otherwise excellent Dominican production: the need for time.', 'The Cabinet Selection is the range that the house ages after rolling. It is not merely a premium cigar: it is a cigar that undergoes additional ageing — the time that the cedar boxes give it.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La Cabinet Selection es la que valida más completamente esa apuesta. No es solo un puro de gama alta: es un puro que recibe un envejecimiento suplementario, concebido para responder a lo que Taylor tenía por la principal carencia de una producción dominicana por lo demás excelente —el tiempo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La Cabinet Selection es la que valida más completamente esa apuesta. No es solo un puro de gama alta: es un puro que recibe un envejecimiento suplementario, concebido para responder a lo que Taylor tenía por la principal carencia de una producción dominicana por lo demás excelente —el tiempo.', 'La Cabinet Selection es la gama que la casa envejece tras el liado. No es solo un puro de gama alta: es un puro que recibe un envejecimiento suplementario —el tiempo que le dan las cajas de cedro.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Cabinet Selection ist es, die diese Wette am vollständigsten einlöst. Sie ist nicht nur eine Zigarre der oberen Reihe: Sie erhält eine zusätzliche Reifung, gedacht als Antwort auf das, was Taylor für den Hauptmangel einer sonst ausgezeichneten dominikanischen Produktion hielt — die Zeit.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Cabinet Selection ist es, die diese Wette am vollständigsten einlöst. Sie ist nicht nur eine Zigarre der oberen Reihe: Sie erhält eine zusätzliche Reifung, gedacht als Antwort auf das, was Taylor für den Hauptmangel einer sonst ausgezeichneten dominikanischen Produktion hielt — die Zeit.', 'Die Cabinet Selection ist die Linie, die das Haus nach dem Rollen reifen lässt. Sie ist nicht nur eine Zigarre der oberen Reihe: Sie erhält eine zusätzliche Reifung — die Zeit, die ihr die Zedernholzkisten geben.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('最完整地兑现了这场赌注的，是 Cabinet Selection。它不只是一支高端雪茄：它经过额外的陈化，专为回应泰勒眼中多米尼加生产在别处都出色、唯独欠缺的那样东西——时间。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '最完整地兑现了这场赌注的，是 Cabinet Selection。它不只是一支高端雪茄：它经过额外的陈化，专为回应泰勒眼中多米尼加生产在别处都出色、唯独欠缺的那样东西——时间。', 'Cabinet Selection 是该公司在卷制之后再行陈化的系列。它不只是一支高端雪茄：它经过额外的陈化——雪松木箱给予它的时间。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('و«كابينت سيليكشن» هي التي تصدّق هذا الرهان على أتمّ وجه. فهي ليست سيجارًا راقيًا فحسب: إنها سيجار يخضع لتعتيق إضافي، صُمِّم ردًّا على ما كان تايلور يعدّه النقص الرئيس في إنتاج دومينيكي ممتاز في ما عدا ذلك — الوقت.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'و«كابينت سيليكشن» هي التي تصدّق هذا الرهان على أتمّ وجه. فهي ليست سيجارًا راقيًا فحسب: إنها سيجار يخضع لتعتيق إضافي، صُمِّم ردًّا على ما كان تايلور يعدّه النقص الرئيس في إنتاج دومينيكي ممتاز في ما عدا ذلك — الوقت.', 'Cabinet Selection هي الخطّ الذي تعتّقه الدار بعد اللفّ. وهي ليست سيجارًا راقيًا فحسب: إنها سيجار يخضع لتعتيق إضافي — الوقت الذي تمنحه إياه صناديق من خشب الأرز.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Ashton Cabinet';

UPDATE `brands` SET
