  `brands` = '[{"desc":"Macanudo, CAO, Toraño ; Punch et Cohiba vendues par Forged depuis janvier 2026","name":"General Cigar","iconic":true},{"desc":"100% US tobacco","name":"CAO America","iconic":false},{"desc":"L''homonyme américaine, née de l''embargo","name":"Cohiba USA","iconic":false},{"desc":"La version américaine, chez General Cigar","name":"Partagás USA","iconic":false},{"desc":"L''américaine d''Altadis, depuis 1969","name":"Romeo y Julieta USA","iconic":false},{"desc":"1895, le plus ancien fabricant familial américain","name":"J.C. Newman","iconic":true},{"desc":"Ce qui reste des ateliers cubains de Miami","name":"El Titan de Bronze","iconic":true},{"desc":"1930, une adresse de la Cinquième Avenue devenue marque","name":"Nat Sherman","iconic":true},{"desc":"La maison d''origine a récupéré son nom en 2001, puis l''a vendu à Altadis","name":"Trinidad USA","iconic":false},{"desc":"Société de distribution de Scandinavian Tobacco Group","name":"Forged Cigar Company","iconic":false},{"desc":"L''hommage d''un fils au poète Heberto Padilla, roulé Calle Ocho","name":"Padilla","iconic":true},{"desc":"Négociant sans fabrique : quatre partenaires, trois pays, un nom de 1896","name":"La Palina","iconic":true},{"desc":"2019 — Desiree Sylver, Washington D.C. ; roulée aux États-Unis, la maison ne nomme pas sa fabrique","name":"Drunk Chicken","iconic":false}]',
