-- ── Contrôle : chaque ligne doit valoir 1 ──
SELECT 'Ashton' AS hote, 'fr' AS lang, 'celebrities' AS quoi, (CAST(JSON_UNQUOTE(JSON_EXTRACT(`celebrities`, '$[0].anecdote')) AS BINARY) = CAST('Levin est un détaillant devenu créateur de marque : sa famille tient Holt''s, à Philadelphie, depuis 1957, il en dirige les affaires depuis 1974 et crée Ashton en 1985, dit holts.com. Ses premiers cigares furent faits chez Tabadom, puis chez Fuente à partir de 1988 selon lui, ou peu après le lancement selon la maison ; les Ashton sont aujourd''hui roulés à la Tabacalera A. Fuente, en République dominicaine, hors la gamme San Cristobal. C''est une marque entièrement construite sur une relation avec un tiers, et elle ne s''en cache pas.' AS BINARY)) AS ok FROM `brands` WHERE `name` = 'Ashton'
UNION ALL SELECT 'Ashton', 'en', 'celebrities', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`celebrities_en`, '$[0].anecdote')) AS BINARY) = CAST('Levin is a retailer who became a brand creator: his family has kept Holt''s, in Philadelphia, since 1957, he has run its affairs since 1974 and he created Ashton in 1985, says holts.com. His first cigars were made at Tabadom, then at Fuente, from 1988 according to him or shortly after the launch according to the house; Ashton cigars are today rolled at Tabacalera A. Fuente, in the Dominican Republic, except for the San Cristobal range. It is a brand built entirely on a relationship with someone else, and it makes no secret of it.' AS BINARY)) FROM `brands` WHERE `name` = 'Ashton'
UNION ALL SELECT 'Ashton', 'es', 'celebrities', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`celebrities_es`, '$[0].anecdote')) AS BINARY) = CAST('Levin es un detallista convertido en creador de marca: su familia lleva Holt''s, en Filadelfia, desde 1957, él dirige sus negocios desde 1974 y crea Ashton en 1985, dice holts.com. Sus primeros puros se hicieron en Tabadom, y luego en Fuente, a partir de 1988 según él o poco después del lanzamiento según la casa; los Ashton se lían hoy en la Tabacalera A. Fuente, en la República Dominicana, con excepción de la gama San Cristobal. Es una marca construida por entero sobre una relación con un tercero, y no lo oculta.' AS BINARY)) FROM `brands` WHERE `name` = 'Ashton'
UNION ALL SELECT 'Ashton', 'de', 'celebrities', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`celebrities_de`, '$[0].anecdote')) AS BINARY) = CAST('Levin ist ein Händler, der zum Markenschöpfer geworden ist: Seine Familie führt Holt''s in Philadelphia seit 1957, er leitet dessen Geschäfte seit 1974 und schafft 1985 Ashton, sagt holts.com. Seine ersten Zigarren wurden bei Tabadom gefertigt, dann bei Fuente, ab 1988 nach seinen Angaben oder kurz nach dem Start nach Angaben des Hauses; die Ashton werden heute in der Tabacalera A. Fuente in der Dominikanischen Republik gerollt, mit Ausnahme der Linie San Cristobal. Eine Marke, die vollständig auf der Beziehung zu einem anderen ruht — und daraus kein Geheimnis macht.' AS BINARY)) FROM `brands` WHERE `name` = 'Ashton'
UNION ALL SELECT 'Ashton', 'zh', 'celebrities', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`celebrities_zh`, '$[0].anecdote')) AS BINARY) = CAST('莱文是零售商出身、后来成为品牌创建者的人：他的家族自1957年起在费城经营 Holt''s，他本人自1974年起掌管其业务，并于1985年创办 Ashton，据 holts.com 称。他最初的雪茄先在 Tabadom 制作，后来在富恩特制作——据他所说是从1988年起，据该公司所说则是品牌推出后不久；Ashton 雪茄如今在多米尼加共和国的 Tabacalera A. Fuente 卷制，San Cristobal 系列除外。这是一个完全建立在他人关系之上的品牌，而它从不讳言这一点。' AS BINARY)) FROM `brands` WHERE `name` = 'Ashton'
UNION ALL SELECT 'Ashton', 'ar', 'celebrities', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`celebrities_ar`, '$[0].anecdote')) AS BINARY) = CAST('ليفين تاجر تجزئة صار منشئ علامة: تتولّى عائلته Holt''s في فيلادلفيا منذ 1957، ويدير شؤونه منذ 1974، وأنشأ Ashton عام 1985، كما يقول holts.com. صُنعت أولى سيجاراته لدى Tabadom، ثم لدى فوينتي، ابتداءً من 1988 بحسب قوله أو بعد الإطلاق بوقت قصير بحسب الدار؛ وتُلفّ سيجارات Ashton اليوم في Tabacalera A. Fuente بالجمهورية الدومينيكية، عدا خط San Cristobal. علامة قائمة بالكامل على علاقة بطرف آخر، وهي لا تخفي ذلك.' AS BINARY)) FROM `brands` WHERE `name` = 'Ashton'
UNION ALL SELECT 'Ashton Cabinet', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Robert Levin, de la famille qui tient Holt''s à Philadelphie, lance Ashton en 1985, dit holts.com. Ses premiers cigares ne sont pas roulés chez Fuente : il dit dans un entretien de 1996 qu''ils furent d''abord faits par Henke Kelner chez Tabadom, puis qu''il a confié la marque aux Fuente en 1988 ; la maison écrit, elle, qu''il s''est associé aux Fuente peu après le lancement. Les Fuente — la maison familiale qui venait de rebâtir sa réputation dans l''île après l''incendie de son usine, en 1980 — roulent aujourd''hui les Ashton à la Tabacalera A. Fuente, en République dominicaine.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('William Ashton Taylor fonda Ashton Cigars à Philadelphie en 1985, sur une idée qui paraît simple aujourd''hui mais qui ne l''était pas alors : avec le bon approvisionnement en tabac et le bon partenaire de fabrication, la République dominicaine pouvait produire des cigares du plus haut niveau. Le partenaire qu''il choisit fut Arturo Fuente — la maison familiale qui venait de rebâtir sa réputation dans l''île après l''incendie de son usine, en 1980.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Robert Levin, of the family that keeps Holt''s in Philadelphia, launched Ashton in 1985, says holts.com. His first cigars were not rolled at Fuente: he says in a 1996 interview that they were first made by Henke Kelner at Tabadom, and that he then entrusted the brand to the Fuentes in 1988; the house, for its part, writes that he teamed up with the Fuentes shortly after the launch. The Fuentes — the family house that had just rebuilt its reputation on the island after the fire at its factory in 1980 — today roll Ashton cigars at Tabacalera A. Fuente, in the Dominican Republic.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('William Ashton Taylor founded Ashton Cigars in Philadelphia in 1985 with a premise that seems simple in retrospect but was genuinely unusual at the time: that the Dominican Republic, given the right tobacco sourcing and the right manufacturing partner, could produce cigars of absolute world-class quality. The partner he chose was Arturo Fuente — the family house that had rebuilt its reputation in the Dominican Republic after a catastrophic factory fire in 1980 and was by 1985 acknowledged as the finest manufacturer on the island.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Robert Levin, de la familia que lleva Holt''s en Filadelfia, lanza Ashton en 1985, dice holts.com. Sus primeros puros no se liaron en Fuente: dice en una entrevista de 1996 que fueron hechos primero por Henke Kelner en Tabadom, y que luego confió la marca a los Fuente en 1988; la casa escribe, por su parte, que se asoció con los Fuente poco después del lanzamiento. Los Fuente —la casa familiar que acababa de rehacer su reputación en la isla tras el incendio de su fábrica, en 1980— lían hoy los Ashton en la Tabacalera A. Fuente, en la República Dominicana.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('William Ashton Taylor fundó Ashton Cigars en Filadelfia en 1985, sobre una idea que hoy parece simple pero que entonces no lo era: con el buen abastecimiento de tabaco y el buen socio de fabricación, República Dominicana podía producir puros del más alto nivel. El socio que eligió fue Arturo Fuente —la casa familiar que acababa de rehacer su reputación en la isla tras el incendio de su fábrica, en 1980.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Robert Levin, aus der Familie, die Holt''s in Philadelphia führt, brachte Ashton 1985 auf den Markt, sagt holts.com. Seine ersten Zigarren wurden nicht bei Fuente gerollt: Er sagt in einem Interview von 1996, sie seien zunächst von Henke Kelner bei Tabadom hergestellt worden, dann habe er die Marke 1988 den Fuentes anvertraut; das Haus schreibt dagegen, er habe sich kurz nach dem Start mit den Fuentes zusammengetan. Die Fuentes — das Familienhaus, das seinen Ruf auf der Insel nach dem Brand seiner Fabrik im Jahr 1980 gerade erst wieder aufgebaut hatte — rollen die Ashton heute in der Tabacalera A. Fuente in der Dominikanischen Republik.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('William Ashton Taylor gründete Ashton Cigars 1985 in Philadelphia, auf einem Gedanken, der heute einfach wirkt, es damals aber nicht war: Mit der richtigen Tabakbeschaffung und dem richtigen Fertigungspartner konnte die Dominikanische Republik Zigarren auf höchstem Niveau hervorbringen. Der Partner, den er wählte, war Arturo Fuente — das Familienhaus, das seinen Ruf auf der Insel gerade nach dem Brand seiner Fabrik im Jahr 1980 wieder aufgebaut hatte.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('罗伯特·莱文（出自在费城经营 Holt''s 的那个家族）于1985年推出 Ashton，据 holts.com 称。他最初的雪茄并不是在富恩特卷制的：他在1996年的一次访谈中说，它们起初由 Henke Kelner 在 Tabadom 制作，后来他在1988年把品牌交给了富恩特家族；该公司则写道，他在品牌推出后不久便与富恩特家族合作。富恩特家族——这家刚在1980年工厂大火之后，于岛上重建声誉的家族字号——如今在多米尼加共和国的 Tabacalera A. Fuente 卷制 Ashton 雪茄。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('1985年，威廉·阿什顿·泰勒在费城创办了阿什顿雪茄，凭的是一个今天看来简单、当时却并不简单的想法：只要有对的烟叶来源与对的制作伙伴，多米尼加共和国就能做出最高水准的雪茄。他选的伙伴是阿图罗·富恩特——那个刚在1980年工厂大火之后，于岛上重建声誉的家族字号。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('أطلق روبرت ليفين، من العائلة التي تتولّى Holt''s في فيلادلفيا، علامة Ashton عام 1985، كما يقول holts.com. ولم تُلفّ أولى سيجاراته لدى فوينتي: يقول في حوار يعود إلى عام 1996 إنها صُنعت في البداية على يد Henke Kelner لدى Tabadom، ثم إنه أوكل العلامة إلى آل فوينتي عام 1988؛ أمّا الدار فتكتب أنه تشارك مع آل فوينتي بعد الإطلاق بوقت قصير. وآل فوينتي — الدار العائلية التي كانت قد أعادت لتوّها بناء سمعتها في الجزيرة بعد حريق مصنعها عام 1980 — يلفّون اليوم سيجار Ashton في Tabacalera A. Fuente بالجمهورية الدومينيكية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('أسّس ويليام آشتون تايلور شركة «آشتون سيغارز» في فيلادلفيا عام 1985، انطلاقًا من فكرة تبدو اليوم بسيطة ولم تكن كذلك حينها: مع التزوّد الصحيح بالتبغ والشريك الصحيح في الصناعة، تستطيع الجمهورية الدومينيكية أن تنتج سيجارًا من أعلى مستوى. والشريك الذي اختاره كان أرتورو فوينتي — الدار العائلية التي كانت قد أعادت لتوّها بناء سمعتها في الجزيرة بعد حريق مصنعها عام 1980.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La Cabinet Selection est la gamme que la maison vieillit après roulage. Ce n''est pas seulement un cigare haut de gamme : c''est un cigare qui subit un vieillissement supplémentaire — le temps que lui donnent les caisses de cèdre.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La Cabinet Selection est celle qui valide le plus complètement ce pari. Ce n''est pas seulement un cigare haut de gamme : c''est un cigare qui subit un vieillissement supplémentaire, conçu pour répondre à ce que Taylor tenait pour le principal manque d''une production dominicaine par ailleurs excellente — le temps.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The Cabinet Selection is the range that the house ages after rolling. It is not merely a premium cigar: it is a cigar that undergoes additional ageing — the time that the cedar boxes give it.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The Cabinet Selection is the expression that validates Taylor''s founding premise most completely. It is not merely a premium cigar — it is a cigar that undergoes an additional aging process specifically designed to address what Taylor considered the main deficiency of otherwise excellent Dominican production: the need for time.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La Cabinet Selection es la gama que la casa envejece tras el liado. No es solo un puro de gama alta: es un puro que recibe un envejecimiento suplementario —el tiempo que le dan las cajas de cedro.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La Cabinet Selection es la que valida más completamente esa apuesta. No es solo un puro de gama alta: es un puro que recibe un envejecimiento suplementario, concebido para responder a lo que Taylor tenía por la principal carencia de una producción dominicana por lo demás excelente —el tiempo.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Die Cabinet Selection ist die Linie, die das Haus nach dem Rollen reifen lässt. Sie ist nicht nur eine Zigarre der oberen Reihe: Sie erhält eine zusätzliche Reifung — die Zeit, die ihr die Zedernholzkisten geben.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die Cabinet Selection ist es, die diese Wette am vollständigsten einlöst. Sie ist nicht nur eine Zigarre der oberen Reihe: Sie erhält eine zusätzliche Reifung, gedacht als Antwort auf das, was Taylor für den Hauptmangel einer sonst ausgezeichneten dominikanischen Produktion hielt — die Zeit.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Cabinet Selection 是该公司在卷制之后再行陈化的系列。它不只是一支高端雪茄：它经过额外的陈化——雪松木箱给予它的时间。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('最完整地兑现了这场赌注的，是 Cabinet Selection。它不只是一支高端雪茄：它经过额外的陈化，专为回应泰勒眼中多米尼加生产在别处都出色、唯独欠缺的那样东西——时间。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Cabinet Selection هي الخطّ الذي تعتّقه الدار بعد اللفّ. وهي ليست سيجارًا راقيًا فحسب: إنها سيجار يخضع لتعتيق إضافي — الوقت الذي تمنحه إياه صناديق من خشب الأرز.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('و«كابينت سيليكشن» هي التي تصدّق هذا الرهان على أتمّ وجه. فهي ليست سيجارًا راقيًا فحسب: إنها سيجار يخضع لتعتيق إضافي، صُمِّم ردًّا على ما كان تايلور يعدّه النقص الرئيس في إنتاج دومينيكي ممتاز في ما عدا ذلك — الوقت.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Ashton Cabinet', 'fr', 'source', (LOCATE(CAST('ashtoncigar.com « Brand History » (lue en octobre 2026, non ' AS BINARY), CAST(`source` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton Cabinet'
UNION ALL SELECT 'Boutique Blends', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Tabacalera La Palma, Tamboril (José « Jochy » Blanco) ; A.J. Fernandez, Nicaragua : La Bohème, Quattro Nicaragua, Pelo de Oro' AS BINARY)) FROM `brands` WHERE `name` = 'Boutique Blends'
UNION ALL SELECT 'Boutique Blends', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Les cigares sont faits par José « Jochy » Blanco, à la Tabacalera La Palma de Tamboril, en République dominicaine, sauf La Bohème, la Quattro Nicaragua et la Pelo de Oro, roulées au Nicaragua chez A.J. Fernandez.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Boutique Blends'
UNION ALL SELECT 'Boutique Blends', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Les cigares sont faits par José « Jochy » Blanco, à la Tabacalera La Palma de Tamboril, en République dominicaine.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Boutique Blends'
UNION ALL SELECT 'Boutique Blends', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Tamboril, Dominican Republic, except La Bohème, the Quattro Nicaragua and the Pelo de Oro, rolled in Nicaragua at A.J. Fernandez.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Boutique Blends'
UNION ALL SELECT 'Boutique Blends', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Tamboril, Dominican Republic.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Boutique Blends'
UNION ALL SELECT 'Boutique Blends', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Tamboril, en la República Dominicana, salvo La Bohème, la Quattro Nicaragua y la Pelo de Oro, liadas en Nicaragua en A.J. Fernandez.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Boutique Blends'
UNION ALL SELECT 'Boutique Blends', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Tamboril, en la República Dominicana.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Boutique Blends'
